// slice seo images — the social cards each route advertises.
//
// The command owns the mechanism (browser context, determinism, capture, card,
// encoding, hashing, cleanup). The app owns the intent (theme, selector,
// template, where the files go). It never edits `seo.json`: that file is
// generated by the app's pipeline, so the cards live in their own manifest
// (`<outDir>/manifest.json`), which the framework merges via `seo.images`.

import fs from 'node:fs';
import fsp from 'node:fs/promises';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { createServer } from 'node:net';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import Print from '../Print.js';
import { loadManifest, writeFileConfirmed } from './support.js';

const CARD = { width: 1200, height: 630 };
const DEVICE_SCALE = 2;
const DEFAULT_BUDGET_KB = 120;
const DEFAULT_OUT_DIR = path.join('src', 'public', 'og');
const FIXED_TIME = new Date('2026-01-15T10:30:00Z');

const DEFAULTS = {
  selector: null,
  template: null,
  theme: 'default',
  budgetKB: DEFAULT_BUDGET_KB
};

// ── pure helpers ────────────────────────────────────────────────────────────

export const routeSlug = (route) => (route === '/'
  ? 'home'
  : String(route)
    .replace(/^\/+|\/+$/g, '')
    .replace(/[^a-z0-9]+/gi, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase());

const escapeHtml = (value) => String(value ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

/** Pixel size from a PNG IHDR or a JPEG SOF marker. */
export function imageSize(buffer) {
  if (buffer.readUInt32BE(0) === 0x89504e47) {
    return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20), type: 'image/png' };
  }
  let offset = 2;
  while (offset < buffer.length - 9) {
    if (buffer[offset] !== 0xff) { offset += 1; continue; }
    const marker = buffer[offset + 1];
    const isSof = marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc;
    if (isSof) {
      return { height: buffer.readUInt16BE(offset + 5), width: buffer.readUInt16BE(offset + 7), type: 'image/jpeg' };
    }
    offset += 2 + buffer.readUInt16BE(offset + 2);
  }
  throw new Error('could not read the image size');
}

const luminance = (hex) => {
  const value = String(hex || '').replace('#', '');
  if (!/^[0-9a-f]{3,8}$/i.test(value)) return null;
  const expand = value.length <= 3 ? value.split('').map((c) => c + c).join('') : value;
  const r = parseInt(expand.slice(0, 2), 16);
  const g = parseInt(expand.slice(2, 4), 16);
  const b = parseInt(expand.slice(4, 6), 16);
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255;
};

/** Routes that deserve a card: indexable literals only. */
export function selectRoutes(manifest, only = null) {
  const wanted = only ? new Set(String(only).split(',').map((item) => item.trim())) : null;
  return Object.entries(manifest?.routes || {})
    .filter(([route, meta]) => {
      if (/\$\{[^}]+\}/.test(route)) return false; // a pattern cannot be enumerated
      if (meta?.robots === false || meta?.robots?.index === false) return false;
      if (meta?.sitemap === false) return false;
      return wanted ? wanted.has(route) : true;
    })
    .map(([route, meta]) => ({ route, meta }))
    .sort((a, b) => a.route.localeCompare(b.route));
}

/** Neutral 1200×630 card. `template` replaces it entirely. */
export function buildCardHtml({ title, route, host, imageData, dark = false, template = null }) {
  if (template) {
    return String(template)
      .replace(/{{title}}/g, escapeHtml(title))
      .replace(/{{route}}/g, escapeHtml(route))
      .replace(/{{host}}/g, escapeHtml(host))
      .replace(/{{image}}/g, imageData || '');
  }

  const palette = dark
    ? { bg: '#0f0d17', ink: '#f4f1fb', muted: '#a99cc4', line: '#2a2438', stage: '#16121f' }
    : { bg: '#fbfaff', ink: '#1a0b2e', muted: '#6b46c1', line: '#e9e2f5', stage: '#ffffff' };

  return `<!DOCTYPE html>
<html><head><meta charset="utf-8" /><style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html, body { width: ${CARD.width}px; height: ${CARD.height}px; overflow: hidden; }
  body {
    font-family: "Source Sans 3", "Segoe UI", "Helvetica Neue", Arial, sans-serif;
    background: ${palette.bg};
    color: ${palette.ink};
    -webkit-font-smoothing: antialiased;
  }
  .card { width: ${CARD.width}px; height: ${CARD.height}px; padding: 44px 56px 30px; display: flex; flex-direction: column; gap: 22px; }
  .eyebrow { font-size: 13px; font-weight: 700; letter-spacing: 3.2px; text-transform: uppercase; color: ${palette.muted}; }
  h1 { font-size: ${String(title).length > 34 ? 38 : String(title).length > 24 ? 44 : 54}px; line-height: 1.05; letter-spacing: -0.02em; }
  .stage {
    flex: 1; min-height: 0; display: flex; align-items: center; justify-content: center;
    overflow: hidden; padding: 26px; border-radius: 18px;
    border: 1px solid ${palette.line}; background: ${palette.stage};
  }
  .stage img { display: block; max-width: 100%; max-height: 100%; }
  footer { display: flex; justify-content: space-between; font-size: 15px; font-weight: 600; color: ${palette.muted}; }
</style></head>
<body><div class="card">
  <div class="eyebrow">${escapeHtml(host)}</div>
  <h1>${escapeHtml(title)}</h1>
  <div class="stage">${imageData ? `<img src="${imageData}" alt="" />` : ''}</div>
  <footer><span>${escapeHtml(route)}</span><span>${escapeHtml(host)}</span></footer>
</div></body></html>`;
}

/** Deterministic JSON: sorted keys, two-space indent. */
const stableJson = (value) => `${JSON.stringify(value, null, 2)}\n`;

// ── project plumbing ────────────────────────────────────────────────────────

export function loadPlaywright(projectRoot) {
  const require = createRequire(path.join(projectRoot, 'package.json'));
  for (const spec of ['playwright', '@playwright/test']) {
    try {
      const mod = require(spec);
      if (mod?.chromium) return mod;
    } catch {
      // try the next one
    }
  }
  throw new Error(
    'Playwright is not installed in this project. Run:\n' +
    '  npm i -D playwright && npx playwright install chromium\n' +
    '(or `pnpm add -D playwright && pnpm exec playwright install chromium`)'
  );
}

const readJson = (file) => JSON.parse(fs.readFileSync(file, 'utf8'));

export function loadImagesConfig(projectRoot, manifest) {
  return { ...DEFAULTS, ...(manifest?.images || {}) };
}

/** The theme the app would show, and whether it is dark. */
export function resolveTheme(projectRoot, config) {
  const configFile = path.join(projectRoot, 'src', 'sliceConfig.json');
  let themeManager = { enabled: false };
  try {
    themeManager = readJson(configFile).themeManager || themeManager;
  } catch {
    // no config: no theme system
  }

  if (!themeManager.enabled) {
    return { themeName: null, dark: false, colorScheme: 'light', localTheme: null };
  }

  const requested = config.theme && config.theme !== 'default' ? config.theme : themeManager.defaultTheme;
  const themeFile = path.join(projectRoot, 'src', 'public', 'Themes', `${requested}.css`);
  if (!fs.existsSync(themeFile)) {
    throw new Error(`Theme "${requested}" not found: expected ${path.relative(projectRoot, themeFile)}`);
  }

  const css = fs.readFileSync(themeFile, 'utf8');
  const background = /--primary-background-color:\s*([^;]+)/.exec(css)?.[1]?.trim();
  const value = luminance(background);
  const dark = value === null ? false : value < 0.5;

  // The theme manager reads localStorage only when the app saves it; otherwise
  // the app's defaultTheme wins and asking for another one has to fail loudly.
  const isRequested = requested !== themeManager.defaultTheme;
  if (isRequested && !themeManager.saveThemeLocally && !themeManager.useBrowserTheme) {
    throw new Error(
      `Cannot capture theme "${requested}": sliceConfig.themeManager has saveThemeLocally and ` +
      'useBrowserTheme off, so the app always starts on ' + themeManager.defaultTheme
    );
  }

  return {
    themeName: requested,
    dark,
    colorScheme: dark ? 'dark' : 'light',
    localTheme: themeManager.saveThemeLocally ? requested : null
  };
}

const freePort = () => new Promise((resolve, reject) => {
  const probe = createServer();
  probe.unref();
  probe.on('error', reject);
  probe.listen(0, '127.0.0.1', () => {
    const { port } = probe.address();
    probe.close(() => resolve(port));
  });
});

const waitForServer = async (baseUrl, timeoutMs = 60_000) => {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      if ((await fetch(`${baseUrl}/api/status`, { signal: AbortSignal.timeout(1500) })).ok) return;
    } catch {
      // still booting
    }
    await new Promise((resolve) => setTimeout(resolve, 200));
  }
  throw new Error(`the dev server did not answer at ${baseUrl}`);
};

/** Boot the project's own server (development mode) on a free port. */
async function startDevServer(projectRoot) {
  const port = await freePort();
  const child = spawn(process.execPath, ['api/index.js'], {
    cwd: projectRoot,
    env: { ...process.env, PORT: String(port) },
    stdio: ['ignore', 'pipe', 'pipe']
  });
  let output = '';
  child.stdout.on('data', (chunk) => { output += chunk; });
  child.stderr.on('data', (chunk) => { output += chunk; });
  const baseUrl = `http://127.0.0.1:${port}`;
  try {
    await waitForServer(baseUrl);
  } catch (error) {
    child.kill();
    throw new Error(`${error.message}\n${output}`);
  }
  return { baseUrl, stop: () => child.kill() };
}

// ── the pipeline ────────────────────────────────────────────────────────────

const settle = async (page, ms = 200) => {
  await page.evaluate(() => new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve))));
  if (ms) await page.waitForTimeout(ms);
};

/** Wait until the DOM stops growing: async builds, no magic delay. */
const waitForStableDom = async (page, { quietMs = 400, timeoutMs = 8_000 } = {}) => {
  const deadline = Date.now() + timeoutMs;
  let last = -1;
  let stableSince = 0;
  while (Date.now() < deadline) {
    const size = await page.evaluate(() => document.body.innerHTML.length);
    if (size === last) {
      if (!stableSince) stableSince = Date.now();
      if (Date.now() - stableSince >= quietMs) return;
    } else {
      last = size;
      stableSince = 0;
    }
    await page.waitForTimeout(100);
  }
};

const trimEdges = async (page, buffer, cut) => {
  const base64 = await page.evaluate(async ({ src, px }) => {
    const image = new Image();
    image.src = `data:image/png;base64,${src}`;
    await image.decode();
    const canvas = document.createElement('canvas');
    canvas.width = image.naturalWidth - px * 2;
    canvas.height = image.naturalHeight - px * 2;
    canvas.getContext('2d').drawImage(image, -px, -px);
    return canvas.toDataURL('image/png').split(',')[1];
  }, { src: buffer.toString('base64'), px: cut });
  return Buffer.from(base64, 'base64');
};

async function captureRoute(page, { baseUrl, route, selector, runner }) {
  await page.goto(`${baseUrl}${route}`, { waitUntil: 'domcontentloaded', timeout: 60_000 });
  if (runner?.prepare) await runner.prepare(page, route);
  await page.evaluate(() => document.fonts.ready.then(() => true));
  await waitForStableDom(page);

  const target = runner?.capture || selector;
  if (target) {
    const shot = await page.locator(target).first().screenshot({ type: 'png', animations: 'disabled' });
    return { kind: 'demo', shot: await trimEdges(page, shot, DEVICE_SCALE) };
  }

  const shot = await page.screenshot({
    type: 'png',
    animations: 'disabled',
    clip: { x: 0, y: 0, width: CARD.width, height: CARD.height }
  });
  return { kind: 'page', shot };
}

const encodeCard = async (cardPage, { title, route, host, shot, kind, dark, template }) => {
  const html = buildCardHtml({
    title,
    route,
    host,
    dark,
    template,
    imageData: shot ? `data:image/png;base64,${shot.toString('base64')}` : null
  });
  await cardPage.setContent(html, { waitUntil: 'load' });
  await cardPage.evaluate(() => document.fonts.ready.then(() => true));

  // PNG keeps flat UI and text crisp; a page slice is photographic enough that
  // JPEG is a third of the size with no visible cost.
  // A page slice is photographic enough for JPEG; an element capture keeps PNG
  // so text and flat UI stay crisp.
  const jpeg = kind === 'page';
  const buffer = await cardPage.screenshot({
    type: jpeg ? 'jpeg' : 'png',
    quality: jpeg ? 86 : undefined,
    animations: 'disabled',
    clip: { x: 0, y: 0, width: CARD.width, height: CARD.height }
  });
  return { buffer, ext: jpeg ? '.jpg' : '.png', type: jpeg ? 'image/jpeg' : 'image/png' };
};

/**
 * Render the cards. Everything is injectable so the tests do not need a browser
 * or a server: `browserFactory`, `baseUrl`, `confirm`.
 */
export async function generateImages(options = {}) {
  const {
    projectRoot,
    only = null,
    dryRun = false,
    yes = false,
    confirm = null,
    runner = null
  } = options;

  const { manifest } = loadManifest(projectRoot);
  if (!manifest) {
    return { errors: ['seo.json not found: run `slice docs:generate` first, or write one'], files: [], patched: null };
  }
  if (!manifest.origin) {
    return { errors: ['seo.json has no origin'], files: [], patched: null };
  }

  const config = {
    ...loadImagesConfig(projectRoot, manifest),
    ...(options.selector ? { selector: options.selector } : {}),
    ...(options.outDir || options.out ? { outDir: options.outDir || options.out } : {})
  };
  const routes = selectRoutes(manifest, only);
  if (!routes.length) {
    return { errors: [`no indexable route matched${only ? ` --only=${only}` : ''}`], files: [], patched: null };
  }

  const configuredOut = config.outDir || DEFAULT_OUT_DIR;
  const outDir = path.isAbsolute(configuredOut) ? configuredOut : path.join(projectRoot, configuredOut);
  const budgetBytes = Math.round((config.budgetKB || DEFAULT_BUDGET_KB) * 1024);
  const theme = resolveTheme(projectRoot, config);
  const template = config.template
    ? fs.readFileSync(path.join(projectRoot, config.template), 'utf8')
    : null;
  const host = String(manifest.origin).replace(/^https?:\/\//, '');
  const runnerModule = runner
    ? (await import(pathToFileURL(path.resolve(projectRoot, runner)).href)).default
    : null;

  const server = options.baseUrl ? null : await startDevServer(projectRoot);
  const baseUrl = options.baseUrl || server.baseUrl;
  const playwright = options.browserFactory ? null : loadPlaywright(projectRoot);
  const browser = options.browserFactory
    ? await options.browserFactory()
    : await playwright.chromium.launch();

  const images = {};
  const files = [];
  let failed = 0;

  try {
    const captureContext = await browser.newContext({
      viewport: { width: 1440, height: 960 },
      deviceScaleFactor: DEVICE_SCALE,
      colorScheme: theme.colorScheme,
      reducedMotion: 'reduce',
      locale: config.locale || 'en-US',
      timezoneId: 'UTC',
      ...(options.storageState ? { storageState: options.storageState } : {})
    });
    if (theme.localTheme) {
      await captureContext.addInitScript((name) => {
        try { localStorage.setItem('sliceTheme', name); } catch { /* storage blocked */ }
      }, theme.localTheme);
    }
    const cardContext = await browser.newContext({
      viewport: CARD,
      deviceScaleFactor: 1,
      colorScheme: theme.colorScheme,
      reducedMotion: 'reduce',
      locale: config.locale || 'en-US'
    });

    for (const { route, meta } of routes) {
      const page = await captureContext.newPage();
      const cardPage = await cardContext.newPage();
      try {
        await page.clock?.setFixedTime?.(FIXED_TIME).catch?.(() => {});
        const capture = await captureRoute(page, { baseUrl, route, selector: config.selector, runner: runnerModule });
        const card = await encodeCard(cardPage, {
          title: meta.title || route,
          route,
          host,
          shot: capture.shot,
          kind: capture.kind,
          dark: theme.dark,
          template
        });

        const hash = createHash('sha256').update(card.buffer).digest('hex').slice(0, 10);
        const fileName = `${routeSlug(route)}-${hash}${card.ext}`;
        const file = path.join(outDir, fileName);

        if (card.buffer.length > budgetBytes) {
          throw new Error(`${(card.buffer.length / 1024).toFixed(1)} KB is over the ${config.budgetKB || DEFAULT_BUDGET_KB} KB budget`);
        }

        if (!dryRun) {
          await fsp.mkdir(outDir, { recursive: true });
          if (!fs.existsSync(file)) await fsp.writeFile(file, card.buffer);
        }

        images[route] = {
          path: `/og/${fileName}`,
          width: CARD.width,
          height: CARD.height,
          type: card.type,
          bytes: card.buffer.length,
          kind: capture.kind
        };
        files.push({ route, file, status: dryRun ? 'would-write' : 'written', bytes: card.buffer.length });
      } catch (error) {
        failed += 1;
        files.push({ route, status: 'failed', error: error.message });
      } finally {
        await page.close();
        await cardPage.close();
      }
    }

    if (failed) {
      return { errors: [`${failed} route(s) failed; the manifest was left untouched`], files, patched: null };
    }

    // --only renders a subset, so merge with what is already there; a full run
    // replaces the set (and the orphan sweep removes what is gone).
    const merged = options.only
      ? { ...(readExistingManifest(outDir)?.images || {}), ...images }
      : images;
    const manifestPayload = {
      version: 1,
      generator: 'slice seo images',
      card: { width: CARD.width, height: CARD.height },
      images: Object.fromEntries(Object.entries(merged).sort(([a], [b]) => a.localeCompare(b)))
    };

    const manifestFile = path.join(outDir, 'manifest.json');
    let manifestStatus = 'written';
    if (dryRun) {
      manifestStatus = 'would-write';
    } else {
      // Generated output, derived from the images just written: no prompt. The
      // overwrite rule belongs to human-reviewed artifacts (the sitemap).
      const written = await writeFileConfirmed(manifestFile, stableJson(manifestPayload), { yes: true });
      manifestStatus = written.status;
      if (written.status === 'unchanged') manifestStatus = 'unchanged';

      // Orphans: an image no manifest entry points at anymore.
      const referenced = new Set(Object.values(manifestPayload.images).map((entry) => path.basename(entry.path)));
      for (const name of fs.readdirSync(outDir)) {
        if (!/\.(png|jpe?g|webp)$/i.test(name) || referenced.has(name)) continue;
        await fsp.unlink(path.join(outDir, name));
        files.push({ route: null, file: path.join(outDir, name), status: 'removed-orphan' });
      }
    }

    return { errors: [], files, patched: { file: manifestFile, status: manifestStatus } };
  } finally {
    await browser.close();
    if (server) server.stop();
  }
}

const readExistingManifest = (outDir) => {
  const file = path.join(outDir, 'manifest.json');
  if (!fs.existsSync(file)) return null;
  try { return readJson(file); } catch { return null; }
};

/** `--check`: no browser, no server. Every indexable route must have a card that fits. */
export function checkImages({ projectRoot, only = null }) {
  const { manifest } = loadManifest(projectRoot);
  if (!manifest) return { errors: ['seo.json not found'], checks: [] };

  const config = loadImagesConfig(projectRoot, manifest);
  const configuredOut = config.outDir || DEFAULT_OUT_DIR;
  const outDir = path.isAbsolute(configuredOut) ? configuredOut : path.join(projectRoot, configuredOut);
  const budgetBytes = Math.round((config.budgetKB || DEFAULT_BUDGET_KB) * 1024);
  const cards = readExistingManifest(outDir)?.images || {};
  const routes = selectRoutes(manifest, only);
  const errors = [];
  const checks = [];

  for (const { route } of routes) {
    const card = cards[route];
    if (!card) { errors.push(`${route} has no card: run \`slice seo images\``); continue; }
    const file = path.join(projectRoot, config.outDir || DEFAULT_OUT_DIR, path.basename(card.path));
    if (!fs.existsSync(file)) { errors.push(`${route}: missing ${card.path}`); continue; }
    const buffer = fs.readFileSync(file);
    const size = imageSize(buffer);
    if (size.width !== CARD.width || size.height !== CARD.height) {
      errors.push(`${route}: ${size.width}×${size.height}, expected ${CARD.width}×${CARD.height}`);
    }
    if (buffer.length > budgetBytes) {
      errors.push(`${route}: ${(buffer.length / 1024).toFixed(1)} KB over the budget`);
    }
    checks.push(route);
  }

  return { errors, checks };
}

// ── the command ─────────────────────────────────────────────────────────────

const STATUS = {
  written: 'written',
  'would-write': 'would write',
  unchanged: 'unchanged',
  'removed-orphan': 'removed orphan',
  failed: 'FAILED'
};

export default async function imagesCommand(options = {}, projectRoot) {
  try {
    if (options.check) {
      const result = checkImages({ projectRoot, only: options.only });
      if (result.errors.length) {
        for (const error of result.errors) Print.error(error);
        Print.error(`SEO images check failed: ${result.errors.length} problem(s).`);
        process.exitCode = 1;
        return;
      }
      Print.success(`SEO images OK: ${result.checks.length} card(s), 1200×630, within budget.`);
      return;
    }

    const result = await generateImages({ projectRoot, ...options });
    for (const file of result.files) {
      const label = STATUS[file.status] || file.status;
      const name = file.route ? `${file.route} → ${path.basename(file.file)}` : path.basename(file.file);
      const message = `${name} (${label}${file.bytes ? `, ${(file.bytes / 1024).toFixed(1)} KB` : ''}${file.error ? `, ${file.error}` : ''})`;
      if (file.status === 'failed') Print.error(message);
      else if (file.status === 'removed-orphan') Print.info(message);
      else Print.success(message);
    }

    if (result.patched) {
      Print.info(`Manifest: ${path.relative(projectRoot, result.patched.file)} (${result.patched.status})`);
    }
    if (result.errors.length) {
      for (const error of result.errors) Print.error(error);
      process.exitCode = 1;
    }
  } catch (error) {
    Print.error('slice seo images failed:', error.message);
    process.exitCode = 1;
  }
}
